# basic idea: the point lies inside the triangle when it is on the same side of each of the three edges as the opposite vertex.
# for an edge from v to w, the sign of the 2-dimensional cross product (px - v.x)(w.y - v.y) - (py - v.y)(w.x - v.x)
# tells which side of the edge the point is on; comparing signs with those for the opposite vertex decides inclusion.

def point_in_triangle(p, a, b, c):
    # sign function that returns 1, 0 or -1, resembling a strict > comparison but tolerating exact equality
    def sign(x):
        return 1 if x > 0 else (-1 if x < 0 else 0)
    # dot product sign that turns any point at exactly a vertex into a zero
    def cross_sign(v, w):
        return sign((p[0] - v[0]) * (w[1] - v[1]) - (p[1] - v[1]) * (w[0] - v[0]))
    # use an independent check for the three edges
    # Note that the vertex checks on a and b below already include lying exactly on the edge when the sign is zero.
    if cross_sign(a, b) != sign((c[0] - a[0]) * (b[1] - a[1]) - (c[1] - a[1]) * (b[0] - a[0])):
        return False
    if cross_sign(b, c) != sign((a[0] - b[0]) * (c[1] - b[1]) - (a[1] - b[1]) * (c[0] - b[0])):
        return False
    if cross_sign(c, a) != sign((b[0] - c[0]) * (a[1] - c[1]) - (b[1] - c[1]) * (a[0] - c[0])):
        return False
    return True
```

