def count_paths(grid):
    """Count the number of right/down paths from top-left to bottom-right in a 0/1 grid.

    Each step can only move right or down, and a cell with a 1 is an obstacle.
    A blocked start or end cell means zero paths.

    Args:
        grid: A 2D list of 0s and 1s.
    Returns:
        An integer count of the paths.
    """
    rows, cols = len(grid), len(grid[0])
    if grid[0][0] or grid[rows - 1][cols - 1]:
        return 0
    dp = [[0] * cols for _ in range(rows)]
    dp[0][0] = 1
    for i in range(1, rows):
        if grid[i][0] == 0:
            dp[i][0] = dp[i - 1][0]
    for j in range(1, cols):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j - 1]
    for i in range(1, rows):
        for j in range(1, cols):
            if grid[i][j] == 0:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
    return dp[rows - 1][cols - 1]
```

