def parse_url_parts(url):
    # Split the scheme from the rest of the URL
    scheme = url.split('://', 1)[0]
    if scheme == url:
        # No '://' found, the entire string is the host only
        return {'scheme': '', 'host': url, 'path': '', 'query': ''}
    rest = url.split('://', 1)[1]
    # Split the host from the path and query
    idx = rest.find('/')
    if idx == -1:
        idx = rest.find('?')
    if idx == -1:
        # No path or query
        host = rest
        path = ''
        query = ''
    else:
        host = rest[:idx]
        if rest[idx] == '/':
            content = rest[idx:]
            idx2 = content.find('?')
            if idx2 == -1:
                path = content
                query = ''
            else:
                path = content[:idx2]
                query = content[idx2 + 1:]
        else:
            host = rest[:idx]
            path = ''
            query = rest[idx:]
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
```

