def coffee_machine_credit(events, prices, stock):
    credit = 0
    dispensed = 0
    # Copy stock so the input is not modified
    final_stock = {name: count for name, count in stock.items())
    for op, value in events:
        if op == "insert":
            credit += value
        elif op == "select":
            name = value
            if name in final_stock and final_stock[name] > 0 and credit >= prices[name]:
                credit -= prices[name]
                final_stock[name] -= 1
                dispensed += 1
    return (credit, final_stock, dispensed)
