def elevator_sweep_stops(start_floor, direction, requests, top_floor):
    # Make a copy so we can remove every visited floor
    remaining = set(requests)
    remaining.discard(start_floor)
    stopped = [start_floor]
    current_floor = start_floor
    while True:
        # If the elevator is on a floor that still needs visiting, visit it now
        if current_floor in remaining:
            stopped.append(current_floor)
            remaining.remove(current_floor)
        # Stop at the top or ground floor (direction 1 reaches top_floor, -1 reaches 1)
        if direction > 0:
            if current_floor == top_floor:
                return stopped
        else:
            if current_floor == 1:
                return stopped
        # Go to the next floor
        current_floor += direction
```

