def dual_traffic_light_sync_count(n_ticks, durations_a, durations_b):
    period_a = durations_a[0] + durations_a[1] + durations_a[2]
    period_b = durations_b[0] + durations_b[1] + durations_b[2]
    counts_a = counts(periods=period_a, phases=durations_a, n_ticks=n_ticks)
    counts_b = counts(periods=period_b, phases=durations_b, n_ticks=n_ticks)
    green_windows_a = windows(n_ticks, counts_a)
    green_windows_b = windows(n_ticks, counts_b)
    return overlapping_ticks(green_windows_a, green_windows_b)

def counts(periods, phases, n_ticks):
    red, green, yellow = phases
    tick, count = 0, [0] * n_ticks
    while tick < n_ticks:
        for t in range(tick, min(n_ticks, tick + red)):
            count[t] = 1
        tick += red
        for t in range(tick, min(n_ticks, tick + green)):
            count[t] = 2
        tick += green
        for t in range(tick, min(n_ticks, tick + yellow)):
            count[t] = 3
        tick += yellow
    return count

def windows(n_ticks, count_list):
    window_start = -1
    for t in range(n_ticks):
        top = count_list[t]
        if top == 2 and window_start < 0:
            window_start = t
        elif window_start >= 0 and top != 2:
            yield (window_start, t)
            window_start = -1
    if window_start >= 0:
        yield (window_start, n_ticks)

def overlapping_ticks(a_windows, b_windows):
    i = j = 0
    while i < len(a_windows) and j < len(b_windows):
        a_start, a_end = a_windows[i]
        b_start, b_end = b_windows[j]
        overlap_start = max(a_start, b_start)
        overlap_end = min(a_end, b_end)
        if overlap_start < overlap_end:
            yield from range(overlap_start, overlap_end)
        if a_end < b_end:
            i += 1
        else:
            j += 1
    return sum(1 for _ in overlapping_ticks)
```

Each light cycles red, green and yellow with its own tick counts, and each contributes pointers to the ticks it is green. The shared-green ticks are those found in both sets; returning their sum gives the required count between 0 and n_ticks - 1 inh हlclusive. For n_ticks of 0 there are no ticks to look at, and that case is handled by producing nothing; no time window is ever empty, because an unstarted window only ends once there is a window that actually starts.

For the inputs (10, (1, 1, 1), (1, 1, 1)) the overlapping windows are (1, 2), (5, 6) and (8, 9), with count 3, and for (10, (1, 1, 1), (2, 2, 2)) the two sets of green windows never overlap, so the count is 0, matching the examples.

