def is_square(p1, p2, p3, p4):
    from math import sqrt, isclose

    def dist2(p, q):
        """Squared distance between p and q, to avoid floating-point issues."""
        return (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2

    def is_length2(l, expected):
        return isclose(l, expected ** 2, abs_tol=1e-12)

    def is_angle2(a, b, c):
        """Dot product of two adjacent edges; zero means a right angle."""
        ab = (b[0] - a[0], b[1] - a[1])
        bc = (c[0] - b[0], c[1] - b[1])
        return isclose(ab[0] * bc[0] + ab[1] * bc[1], 0, abs_tol=1e-12)

    counts = {}
    d = dist2(p1, p2)
    for i, p in enumerate([p2, p3, p4] + [p1]):
        d = dist2(p, [p3, p4, p1, p2][i])
        counts[d] = counts.get(d, 0) + 1
    if set(counts.values()) != {2}:  # Two pairs of equal lengths
        return False

    for i, p in enumerate([p1, p2, p3, p4]):
        if not is_angle2(p, [p2, p3, p4][i], [p2, p3, p4][i + 1]):
            return False
    return True
