def equal_under_rotation(grid1, grid2):
    """Return whether some 0, 90, 180, or 270-degree rotation of the first grid equals the second exactly, same dimensions and values in the same positions."""
    # Empty grids are equal
    if not grid1:
        return not grid2
    # Only compare grids of the same size
    rows1, cols1 = len(grid1), len(grid1[0])
    rows2, cols2 = len(grid2), len(grid2[0])
    if rows1 != rows2 or cols1 != cols2:
        return False
    # Build each of the four rotations and compare
    def rotate90(grid):
        rows, cols = len(grid), len(grid[0])
        new = [[0] * rows for _ in range(cols)]
        for i in range(rows):
            for j in range(cols):
                new[j][rows - 1 - i] = grid[i][j]
        return new
    def rotate180(grid):
        # rotate90 twice
        return rotate90(rotate90(grid))
    def rotate270(grid):
        # rotate90 three times, or one anticlockwise
        return rotate90(rotate90(rotate90(grid)))
    return grid2 == grid1 or grid2 == rotate90(grid1) or grid2 == rotate180(grid1) or grid2 == rotate270(grid1)
```

