def count_islands(grid):
    if not grid:
        return 0

    def dfs(i, j):
        # Visit every one cell reachable from (i, j)
        while True:
            # Mark cell (i, j) as 0 to stop revisiting
            grid[i][j] = 0
            # Explore neighbors in row-major order
            for delta in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + delta[0], j + delta[1]
                if 0 <= ni < len(grid) and 0 <= nj < len(grid[ni]) and grid[ni][nj] == 1:
                    dfs(ni, nj)
                    break
            else:
                break
            i, j = ni, nj

    result = 0
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == 1:
                dfs(i, j)
                result += 1
    return result
```

