def rate_limiter_allowed(timestamps, limit, window):
    allowed = []
    for t in timestamps:
        count = 0
        for t_j in timestamps:
            if t_j > t - window and t_j <= t:
                count += 1
                if count > limit:
                    break
        allowed.append(count <= limit)
    return allowed
```

