def is_point_on_segment(p, a, b):
    """Return True exactly when p lies on the segment from a to b."""
    # (0, 0), (0, 0), (2, 2): both endpoints are the same
    if a == b:
        return p == a  # any point on this line is that one point
    # Distinct endpoints define a direction (only x matters here)
    if a[0] == b[0]:
        return p[0] == a[0] and min(a[1], b[1]) <= p[1] <= max(a[1], b[1])
    # A point lies on the segment when its x is between the endpoints and the y matches the linear value
    # Keep the code general by using integers when exactness matters
    # The linear value is of the form mu * (y1 - y0) + y0 where mu is between 0 and 1, so compute it rounded to integer: floor(mu) is 0 and ceil(mu) is 1
    mu_floor = int((p[0] - a[0]) / (b[0] - a[0]))  # same as min(0, b[0] - p[0], p[0] - a[0]) <= max(...)
    mu_ceil = int((p[0] - a[0] + b[0] - a[0] - 1) / (b[0] - a[0]))  # same as mu_floor
    if mu_floor != mu_ceil:
        return False  # x - a[0] is *not* between 0 and b[0] - a[0]
    return p[1] == round(mu_floor * (b[1] - a[1]) + a[1])
