                r, c = nr, nc
            grid[i][j] = grid[r][c]
        if angle == 90:
            return transpose(grid)
        if angle == 180:
            return reverse_rows(copy(grid))
        if angle == 270:
            return transpose(reverse_rows(copy(grid)))
    return grid

def transpose(grid):
    return [list(row) for row in zip(*grid)]

def reverse_rows(grid):
    return [row[:] for row in reversed(grid)]
