        rotated = rotate_clockwise(grid1, q)
        if rotated == grid2:
            return True
    return False

def rotate_clockwise(grid, times):
    result = grid.copy()
    for _ in range(times):
        result = [list(row) for row in zip(*result[::-1])]
    return result
