def max_value_position(grid):
    from itertools import chain
    it = chain.from_iterable(grid)
    maximum, i = next(it), 0
    while True:
        try:
            val = next(it)
            if val > maximum:
                maximum, i = val, i
            i += 1
        except StopIteration:
