def count_paths(grid):
    from itertools import product

    def in_bounds(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[r])

    def good_cell(r, c):
        return in_bounds(r, c) and grid[r][c] == 0

    def path(r, c, seen):
        if (r, c) in seen:
            return 0
        seen.add((r, c))
        if r == len(grid) - 1 and c == len(grid[r]) - 1:
            return 1
        right = path(r, c + 1, seen) if good_cell(r, c + 1) else 0
        down = path(r + 1, c, seen) if good_cell(r + 1, c) else 0
        return right + down
    return path(0, 0, set())
