def is_checkerboard(grid):
    """A grid counts as a checkerboard if it has at most two different values, and each cell differs from its row and column neighbours, with agreement on the parity of its row and column indices; a one-cell or empty grid counts as valid."""
    # Record which values the parity set at each cell holds.
    for ri, row in enumerate(grid):
        for ci, val in enumerate(row):
            parity = (ri + ci) % 2
            value_sets = {0: set(), 1: set()}
            value_sets[parity].add(val)
            for ci2, val2 in enumerate(row):
                if (ci2 + ri) % 2 != parity and val2 == val:
                    return False
    return True
```

