def elevator_door_floor(commands, min_floor, max_floor):
    floor = min_floor
    door = 'CLOSED'
    for cmd in commands:
        if door == 'CLOSED':
            if cmd == 'open':
                door = 'OPEN'
            elif cmd == 'close':
                door = 'CLOSED'
            elif cmd == 'up':
                if floor < max_floor:
                    floor += 1
            elif cmd == 'down':
