def normalize_rectangle(p1, p2):
    """Given two opposite corners of an axis-aligned rectangle,
    in any order, return its canonical form with x1 <= x2 and y1 <= y2."""
    if p1[0] < p2[0]:
        x1, x2 = p1[0], p2[0]
    else:
        x1, x2 = p2[0], p1[0]
    if p1[1] < p2[1]:
